function blankProgress(n){return Array.from({length:n},()=>({lesson:false,solved:0}))}
function loadGM(){try{const p=JSON.parse(localStorage.getItem(GM_KEY));if(p?.course?.length===5)return p}catch{}return{stars:0,streak:1,unlocked:0,currentStage:0,course:blankProgress(5)}}
function loadXQ(){try{const p=JSON.parse(localStorage.getItem(XQ_KEY));if(p?.course?.length===6)return p}catch{}return{stars:0,streak:1,unlocked:0,currentStage:0,course:blankProgress(6)}}
function loadGo(){try{const p=JSON.parse(localStorage.getItem(GO_KEY));if(p?.course?.length===6)return p}catch{}return{stars:0,streak:1,unlocked:0,currentStage:0,course:blankProgress(6)}}
function loadCube(){try{const p=JSON.parse(localStorage.getItem(CUBE_KEY));if(p?.course?.length===7)return p}catch{}return{stars:0,streak:1,unlocked:0,currentStage:0,course:blankProgress(7)}}
const state={game:null,mode:null,stage:0,board:[],turn:'r',over:false,sound:true,level:'easy',selected:null,legal:[],hint:null,mistakes:0,moves:0,puzzleIndex:0,puzzleStep:0,puzzle:null,nextAction:'course',goHistory:[],passes:0,cube:[],cubeSequence:[],cubeStartedAt:0,gm:loadGM(),xq:loadXQ(),go:loadGo(),cubeProgress:loadCube()};

function gameProgress(game=state.game){return game==='gomoku'?state.gm:game==='xiangqi'?state.xq:game==='go'?state.go:state.cubeProgress}
function curriculum(game=state.game){return game==='gomoku'?GM_CURRICULUM:game==='xiangqi'?XQ_CURRICULUM:game==='go'?GO_CURRICULUM:CUBE_CURRICULUM}
function puzzleTotal(){return state.game==='gomoku'?6:4}
function currentStage(){return curriculum()[state.stage]}
function stageProgress(i=state.stage){return gameProgress().course[i]}
function stagePercent(i=state.stage){const p=stageProgress(i),n=puzzleTotal();return Math.round((p.lesson?20:0)+Math.min(p.solved,n)/n*80)}
function isStageDone(i){const p=stageProgress(i);return p.lesson&&p.solved>=puzzleTotal()}
function save(){if(state.game){const p=gameProgress();p.currentStage=state.stage;const key=state.game==='gomoku'?GM_KEY:state.game==='xiangqi'?XQ_KEY:state.game==='go'?GO_KEY:CUBE_KEY;localStorage.setItem(key,JSON.stringify(p))}updateHub();updateCourse()}
function speak(text){if(!state.sound||!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=.9;u.pitch=1.08;speechSynthesis.speak(u)}
function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$('#hallBtn').classList.toggle('hidden',id==='hubView');window.scrollTo({top:0,behavior:'smooth'})}

function overall(game){const old=state.game;state.game=game;const all=curriculum(),sum=all.reduce((a,_,i)=>a+stagePercent(i),0);state.game=old;return Math.round(sum/all.length)}
function updateHub(){const gp=overall('gomoku'),xp=overall('xiangqi'),op=overall('go'),cp=overall('cube');$('#gomokuHubProgress').textContent=gp+'%';$('#gomokuHubBar').style.width=gp+'%';$('#xiangqiHubProgress').textContent=xp+'%';$('#xiangqiHubBar').style.width=xp+'%';$('#goHubProgress').textContent=op+'%';$('#goHubBar').style.width=op+'%';$('#cubeHubProgress').textContent=cp+'%';$('#cubeHubBar').style.width=cp+'%';$('#totalStars').textContent=(state.gm.stars||0)+(state.xq.stars||0)+(state.go.stars||0)+(state.cubeProgress.stars||0);$('#streakCount').textContent=Math.max(state.gm.streak||1,state.xq.streak||1,state.go.streak||1,state.cubeProgress.streak||1)}
function openGame(game){state.game=game;state.stage=Math.min(gameProgress().currentStage||0,curriculum().length-1);updateCourse();showView('courseView')}
function goHub(){state.game=null;window.speechSynthesis?.cancel();updateHub();showView('hubView')}
function updateCourse(){if(!state.game)return;const c=currentStage(),p=stageProgress(),total=puzzleTotal(),isGM=state.game==='gomoku',isXQ=state.game==='xiangqi',isGo=state.game==='go',isCube=state.game==='cube';$('#courseHero').classList.toggle('gomoku',isGM);$('#courseHero').classList.toggle('cube',isCube);$('#courseBadge').textContent=`第 ${state.stage+1} 阶段 · ${c.rank}`;$('#courseTitle').textContent=c.hero;$('#courseDesc').textContent=c.desc;$('#courseSymbol').textContent=isCube?'▦':isGM||isGo?'●':(c.pieces?.[0]||'帥');$('#gameLabel').textContent=isGM?'五子棋冒险':isXQ?'中国象棋学堂':isGo?'围棋启蒙岛':'魔方成长营';$('#stagePercent').textContent=stagePercent();$('#lessonCardTitle').textContent=c.lesson;$('#lessonCardDesc').textContent=c.rule;$('#puzzleCardTag').textContent=`互动闯关 · ${Math.min(p.solved,total)}/${total}`;$('#puzzleCardTitle').textContent=c.puzzleTitle;$('#puzzleCardDesc').textContent=isGM?'在变化棋形中找到关键手':isXQ?'在棋盘上亲手走出正确答案':isGo?'数清每一口气，找到关键落点':'看公式、动手转，让颜色一步步回家';$('#battleCardTitle').textContent=c.battle;$('#battleCardTag').textContent=isCube?'记忆还原 · 随时可玩':'自由对战 · 随时可玩';$('#battleCardDesc').textContent=isCube?'选择步数难度，练习稳定复原和少停顿':'把学会的招式用进棋局';$('#battleCardAction').textContent=isCube?'去挑战 →':'去对战 →';$('#roadTitle').textContent=isGM?'五段棋力冒险':isXQ?'六站象棋启蒙':isGo?'六站围棋启蒙':'七站魔方成长路线';const cards=$$('.mission-card');cards[0].classList.toggle('complete',p.lesson);cards[1].classList.toggle('complete',p.solved>=total);const prog=gameProgress();$('#stagePath').innerHTML=curriculum().map((s,i)=>{const locked=i>prog.unlocked,done=isStageDone(i),active=i===state.stage;return`<button class="stage-node ${done?'done':''} ${active?'active':''}" data-stage="${i}" ${locked?'disabled':''}><span class="stage-emoji">${locked?'🔒':s.emoji}</span><b>${i+1}. ${s.title}</b><small>${s.rank}<br>${done?'已完成，可复习':locked?'完成上一站后开启':stagePercent(i)+'% 完成'}</small><span class="node-status">${done?'✓':active?'正在学':locked?'未解锁':'可学习'}</span></button>`}).join('');$$('.stage-node:not(:disabled)').forEach(b=>b.onclick=()=>{state.stage=+b.dataset.stage;save();$('.today-section').scrollIntoView({behavior:'smooth'})})}

function clearBoard(){state.selected=null;state.legal=[];state.hint=null;state.mistakes=0;state.moves=0;state.passes=0;state.goHistory=[];state.cubeSequence=[];state.over=false;state.turn=state.game==='xiangqi'?'r':1;$('#celebration').classList.remove('show');$('#lessonPanel').classList.remove('show');$('#passBtn').classList.add('hidden');$('#cubeControls').classList.add('hidden')}
function setupMode(mode,battleLevel){state.mode=mode;if(mode==='battle')state.level=battleLevel||currentStage().level;clearBoard();$('.level-card').style.display=mode==='battle'?'block':'none';$('#levelKicker').textContent=state.game==='cube'?'训练难度':'电脑难度';$('#levelTitle').textContent=state.game==='cube'?'选择还原步数':'选择挑战伙伴';$('#boardWrap').classList.toggle('xiangqi-board',state.game==='xiangqi');$('#boardWrap').classList.toggle('cube-board',state.game==='cube');if(state.game==='gomoku')setupGM(mode);else if(state.game==='xiangqi')setupXQ(mode);else if(state.game==='go')setupGo(mode);else setupCube(mode);showView('gameView');draw();speak($('#coachText').textContent)}
function setupGM(mode){canvas.width=660;canvas.height=660;state.board=Array.from({length:11},()=>Array(11).fill(0));const c=currentStage();$('#coachAvatar').textContent='★';$('#tinyRule').innerHTML='<b>专业思考：</b>先看连五，再看冲四、活三和双重威胁。候选点不用多，关键是算清对手最强的回答。';if(mode==='lesson'){const d=gmPuzzle(state.stage,0);gmPut(d.black,1);gmPut(d.white,2);state.hint={x:d.steps[0][0],y:d.steps[0][1]};showLesson(c);$('#moveCount').textContent='知识卡';$('#puzzleProgress').textContent='理解方法比记住答案更重要'}else if(mode==='puzzle'){const p=stageProgress();state.puzzleIndex=p.solved<6?p.solved:Math.floor(Math.random()*6);state.puzzle=gmPuzzle(state.stage,state.puzzleIndex);state.puzzleStep=0;gmPut(state.puzzle.black,1);gmPut(state.puzzle.white,2);$('#modeKicker').textContent=`第 ${state.stage+1} 阶段 · 第 ${state.puzzleIndex+1} 题`;$('#modeTitle').textContent=c.puzzleTitle;$('#coachText').textContent=state.puzzle.coach;gmPuzzleProgress()}else{syncLevel();['会找一步胜负点','会比较进攻与防守','威胁搜索并预判三层'].forEach((t,i)=>$$('[data-level] small')[i].textContent=t);$('#modeKicker').textContent=`第 ${state.stage+1} 阶段 · 专业实战`;$('#modeTitle').textContent=`五子棋实战 · 挑战${LEVEL_NAMES[state.level]}棋手`;const notes={easy:'小鸡会看一步连五和防守，适合练习基本棋形。',medium:'狐狸会比较活三、冲四和防守价值。',hard:'狮子会用候选点和 Alpha-Beta 搜索，预判连续威胁。'};$('#coachText').textContent=`当前对手：${LEVEL_NAMES[state.level]}。${notes[state.level]}`;$('#moveCount').textContent='已走 0 步';$('#puzzleProgress').textContent='先连成 5 颗就获胜';updateTurn()}}
function setupXQ(mode){canvas.width=594;canvas.height=660;const c=currentStage();$('#coachAvatar').textContent='帥';$('#tinyRule').innerHTML='<b>记住：</b>红方先走。选中棋子后，绿色圆点就是可以走的位置。';if(mode==='lesson'){state.board=xqFromPieces(XQ_PUZZLES[state.stage][0].pieces);showLesson(c);$('#moveCount').textContent='知识卡';$('#puzzleProgress').textContent='先学规则，再亲手走棋'}else if(mode==='puzzle'){const p=stageProgress();state.puzzleIndex=p.solved<4?p.solved:Math.floor(Math.random()*4);state.puzzle=XQ_PUZZLES[state.stage][state.puzzleIndex];state.board=xqFromPieces(state.puzzle.pieces);$('#modeKicker').textContent=`第 ${state.stage+1} 站 · 第 ${state.puzzleIndex+1} 题`;$('#modeTitle').textContent=c.puzzleTitle;$('#coachText').textContent=state.puzzle.coach;$('#moveCount').textContent=`第 ${state.puzzleIndex+1} / 4 题`;$('#puzzleProgress').textContent='先选中红棋，再选择落点';updateTurn()}else{state.board=xqInitial();['会漏看好棋，适合热身','会算你下一步的反击','会推演四层并保护重要棋子'].forEach((t,i)=>$$('[data-level] small')[i].textContent=t);syncLevel();$('#modeKicker').textContent=`第 ${state.stage+1} 站 · 完整对局`;$('#modeTitle').textContent=`象棋实战 · 挑战${LEVEL_NAMES[state.level]}将军`;const notes={easy:'小鸡多数时候随意走，也会漏掉好棋。',medium:'狐狸会先想你下一步怎样吃子或将军，再决定自己的走法。',hard:'狮子会连续推演双方四层走法，重视防守、兑子和将军。'};$('#coachText').textContent=`当前对手：${LEVEL_NAMES[state.level]}。${notes[state.level]}`;$('#moveCount').textContent='已走 0 步';$('#puzzleProgress').textContent='目标：保护帅，捉住对方的将';updateTurn()}}
function setupGo(mode){canvas.width=660;canvas.height=660;const c=currentStage();$('#coachAvatar').textContent='○';$('#tinyRule').innerHTML='<b>专业思考：</b>先看打吃和逃子，再比较连接、厚薄与地盘。狮子会模拟许多后续变化。';if(mode==='lesson'){state.puzzle=GO_PUZZLES[state.stage][0];state.board=goFromPuzzle(state.puzzle);showLesson(c);$('#pieceDemo').innerHTML='<span class="stone black"></span><span class="stone white"></span>';$('#moveCount').textContent='知识卡';$('#puzzleProgress').textContent='先学会数气，再到棋盘上试一试'}else if(mode==='puzzle'){const p=stageProgress();state.puzzleIndex=p.solved<4?p.solved:Math.floor(Math.random()*4);state.puzzle=GO_PUZZLES[state.stage][state.puzzleIndex];state.board=goFromPuzzle(state.puzzle);$('#modeKicker').textContent=`第 ${state.stage+1} 岛 · 第 ${state.puzzleIndex+1} 题`;$('#modeTitle').textContent=c.puzzleTitle;$('#coachText').textContent=state.puzzle.coach;$('#moveCount').textContent=`第 ${state.puzzleIndex+1} / 4 题`;$('#puzzleProgress').textContent='你执黑棋，找到关键交叉点';updateTurn()}else{state.board=goEmpty();state.goHistory=[goSerial(state.board)];syncLevel();['认识气与合法落点','会算打吃、逃子和连接','蒙特卡洛模拟气与地盘'].forEach((t,i)=>$$('[data-level] small')[i].textContent=t);$('#passBtn').classList.remove('hidden');$('#modeKicker').textContent=`第 ${state.stage+1} 岛 · 9 路专业实战`;$('#modeTitle').textContent=`围棋实战 · 挑战${LEVEL_NAMES[state.level]}岛主`;const notes={easy:'小鸡重视合法落子和气，偶尔会漏看大场。',medium:'狐狸会比较打吃、逃子、连接和地盘。',hard:'狮子会用蒙特卡洛模拟后续变化，再选择胜率更高的落点。'};$('#coachText').textContent=`当前对手：${LEVEL_NAMES[state.level]}。${notes[state.level]}`;$('#moveCount').textContent='已走 0 手';$('#puzzleProgress').textContent='黑棋先行 · 围地多的一方获胜';updateTurn()}}
const CUBE_FACES=['U','R','F','D','L','B'];
const CUBE_NORMAL={U:[0,1,0],D:[0,-1,0],F:[0,0,1],B:[0,0,-1],R:[1,0,0],L:[-1,0,0]};
const CUBE_COLORS={U:'#f5f6f2',D:'#ffd43b',F:'#35ad68',B:'#4778dc',R:'#eb5147',L:'#f39235'};
function cubeSpec(face,r,c){if(face==='U')return{p:[c-1,1,r-1],n:[0,1,0]};if(face==='D')return{p:[c-1,-1,1-r],n:[0,-1,0]};if(face==='F')return{p:[c-1,1-r,1],n:[0,0,1]};if(face==='B')return{p:[1-c,1-r,-1],n:[0,0,-1]};if(face==='R')return{p:[1,1-r,1-c],n:[1,0,0]};return{p:[-1,1-r,c-1],n:[-1,0,0]}}
function cubeSolvedState(){const out=[];CUBE_FACES.forEach(face=>{for(let r=0;r<3;r++)for(let c=0;c<3;c++)out.push({...cubeSpec(face,r,c),color:face})});return out}
function cubeVectorTurn(v,a){const d=a[0]*v[0]+a[1]*v[1]+a[2]*v[2],cross=[a[1]*v[2]-a[2]*v[1],a[2]*v[0]-a[0]*v[2],a[0]*v[1]-a[1]*v[0]];return[a[0]*d-cross[0],a[1]*d-cross[1],a[2]*d-cross[2]]}
function cubeMove(token){const face=token[0],a=CUBE_NORMAL[face],times=token.includes('2')?2:token.includes("'")?3:1;for(let t=0;t<times;t++)state.cube.forEach(s=>{if(s.p[0]*a[0]+s.p[1]*a[1]+s.p[2]*a[2]===1){s.p=cubeVectorTurn(s.p,a);s.n=cubeVectorTurn(s.n,a)}})}
function cubeSticker(face,r,c){const q=cubeSpec(face,r,c);return state.cube.find(s=>s.p.every((v,i)=>v===q.p[i])&&s.n.every((v,i)=>v===q.n[i]))?.color||face}
function cubeExpand(seq){return seq.flatMap(t=>t.includes('2')?[t[0],t[0]]:[t])}
function cubeInverse(seq){return[...seq].reverse().map(t=>t.includes('2')?t:t.includes("'")?t[0]:t+"'")}
function cubeIsSolved(){return CUBE_FACES.every(face=>{const colors=[];for(let r=0;r<3;r++)for(let c=0;c<3;c++)colors.push(cubeSticker(face,r,c));return colors.every(x=>x===colors[4])})}
function cubeRenderControls(){const tokens=['U',"U'",'R',"R'",'F',"F'",'L',"L'",'D',"D'",'B',"B'"];$('#cubeControls').innerHTML=tokens.map(t=>`<button data-cube-move="${t}" aria-label="转动 ${t}">${t}</button>`).join('')+'<span class="cube-help">没有撇号＝顺时针　有撇号＝逆时针（面对那一面看）</span>';$('#cubeControls').classList.remove('hidden');$$('[data-cube-move]').forEach(b=>b.onclick=()=>cubeChoose(b.dataset.cubeMove))}
function cubePrepare(sequence){state.cube=cubeSolvedState();state.cubeSequence=cubeExpand(sequence);cubeInverse(state.cubeSequence).forEach(cubeMove);state.puzzleStep=0;state.moves=0;state.cubeStartedAt=Date.now()}
function cubeBattleSequence(){const length=state.level==='easy'?3:state.level==='medium'?6:10,faces=state.level==='easy'?['U','R','F']:state.level==='medium'?['U','R','F','L']:CUBE_FACES,out=[];while(out.length<length){const face=faces[Math.floor(Math.random()*faces.length)];if(out.at(-1)?.[0]===face)continue;out.push(face+(Math.random()<.48?"'":''))}return out}
function setupCube(mode){canvas.width=660;canvas.height=465;const c=currentStage();$('#coachAvatar').textContent='▦';$('#tinyRule').innerHTML='<b>魔方三步：</b>先观察目标块，再读一个动作，最后检查颜色有没有更接近中心。';if(mode==='lesson'){state.cube=cubeSolvedState();showLesson(c);const demo=state.stage===0?['white','yellow','green','blue','red','orange'].map(x=>`<i class="cube-color-demo ${x}"></i>`).join(''):CUBE_PUZZLES[state.stage][0].solution.slice(0,6).map(x=>`<span class="cube-move-demo">${x}</span>`).join('');$('#pieceDemo').innerHTML=demo;$('#turnBanner').innerHTML='<b>先观察，再动手</b><small>今天只学一个新本领</small>';$('#moveCount').textContent='知识卡';$('#puzzleProgress').textContent='理解颜色和方向，比转得快更重要'}else if(mode==='puzzle'){const p=stageProgress();state.puzzleIndex=p.solved<4?p.solved:Math.floor(Math.random()*4);state.puzzle=CUBE_PUZZLES[state.stage][state.puzzleIndex];cubePrepare(state.puzzle.solution);cubeRenderControls();$('#modeKicker').textContent=`第 ${state.stage+1} 站 · 第 ${state.puzzleIndex+1} 题`;$('#modeTitle').textContent=c.puzzleTitle;$('#coachText').textContent=state.puzzle.coach;$('#turnBanner').innerHTML='<b>轮到你转魔方</b><small>从左到右完成动作</small>';$('#moveCount').textContent=`第 ${state.puzzleIndex+1} / 4 题`;cubeProgressText()}else{cubePrepare(cubeBattleSequence());cubeRenderControls();['3 步热身，有提示','6 步接力，练习少停顿','10 步挑战，考验稳定记忆'].forEach((t,i)=>$$('[data-level] small')[i].textContent=t);syncLevel();$('#modeKicker').textContent=`第 ${state.stage+1} 站 · 记忆还原`;$('#modeTitle').textContent=`魔方挑战 · ${LEVEL_NAMES[state.level]}级`;$('#coachText').textContent=`记住这组 ${state.cubeSequence.length} 步还原动作。每一步做对，颜色都会更接近整齐。`;$('#turnBanner').innerHTML='<b>记忆还原开始</b><small>稳稳转，不着急</small>';cubeProgressText()}}
function cubeProgressText(){$('#moveCount').textContent=state.mode==='battle'?`已完成 ${state.puzzleStep} / ${state.cubeSequence.length} 步`:`第 ${state.puzzleIndex+1} / 4 题 · ${state.puzzleStep}/${state.cubeSequence.length} 步`;const next=state.cubeSequence[state.puzzleStep];$('#puzzleProgress').textContent=next?`下一步：${next}`:'检查复原结果'}
function cubeChoose(token){if(state.over)return;const expected=state.cubeSequence[state.puzzleStep];if(token!==expected){state.mistakes++;$('#coachText').textContent=state.mistakes>=2?`再看一眼：下一步是 ${expected}。撇号表示逆时针。`:'方向还差一点。面对要转的那一面，再判断顺时针或逆时针。';speak($('#coachText').textContent);return}cubeMove(token);state.puzzleStep++;state.moves++;draw();cubeProgressText();if(state.puzzleStep===state.cubeSequence.length){if(!cubeIsSolved()){$('#coachText').textContent='动作都完成了，再检查一次中心和同色伙伴。';return}state.over=true;setTimeout(()=>state.mode==='battle'?finishCubeBattle():finishPuzzle(),280)}else $('#coachText').textContent=`做对了！下一步是 ${state.cubeSequence[state.puzzleStep]}。`}
function finishCubeBattle(){const seconds=Math.max(1,Math.round((Date.now()-state.cubeStartedAt)/1000)),reward=state.level==='hard'?4:state.level==='medium'?3:2;gameProgress().stars+=reward;state.nextAction='restartBattle';save();showResult('魔方复原成功！',`${state.moves} 步全部正确，用时 ${seconds} 秒。下一次试着更少停顿。`,reward)}
function drawCube(){ctx.fillStyle='#eef3ff';ctx.fillRect(0,0,canvas.width,canvas.height);const pos={U:[201,12],L:[69,144],F:[201,144],R:[333,144],B:[465,144],D:[201,276]},size=38,gap=4;CUBE_FACES.forEach(face=>{const[x,y]=pos[face];ctx.fillStyle='#202b35';ctx.fillRect(x-7,y-7,3*size+2*gap+14,3*size+2*gap+14);for(let r=0;r<3;r++)for(let c=0;c<3;c++){ctx.fillStyle=CUBE_COLORS[cubeSticker(face,r,c)];ctx.fillRect(x+c*(size+gap),y+r*(size+gap),size,size);ctx.strokeStyle='rgba(20,30,39,.28)';ctx.lineWidth=2;ctx.strokeRect(x+c*(size+gap)+1,y+r*(size+gap)+1,size-2,size-2)}});ctx.fillStyle='#34465a';ctx.font='700 15px Microsoft YaHei';ctx.textAlign='center';ctx.fillText('上 U',264,139);ctx.fillText('左 L',132,271);ctx.fillText('前 F',264,271);ctx.fillText('右 R',396,271);ctx.fillText('后 B',528,271);ctx.fillText('下 D',264,403);ctx.fillStyle='#738198';ctx.font='13px Microsoft YaHei';const done=state.cubeSequence.length?`${state.puzzleStep} / ${state.cubeSequence.length} 步`:'六个中心决定六面的颜色';ctx.fillText(done,330,445)}

function showLesson(c){$('#modeKicker').textContent=`第 ${state.stage+1} 阶段 · 新本领`;$('#modeTitle').textContent=c.lesson;$('#coachText').textContent='先看懂方法，再到互动区亲手试一试。';$('#lessonTitle').textContent=c.lesson;$('#lessonText').textContent=c.lessonText;$('#lessonRule').textContent=c.rule;$('#pieceDemo').innerHTML=(c.pieces||[]).map(x=>`<span class="demo-piece">${x}</span>`).join('');$('#turnBanner').innerHTML=state.game==='xiangqi'?'<span class="demo-piece" style="width:28px;height:28px;font-size:15px;border-width:2px">帥</span><b>红方先行</b><small>棋子走在线的交叉点</small>':`<span class="stone black"></span><b>${state.game==='go'?'黑棋先行':state.game==='cube'?'观察颜色':'你执黑棋'}</b><small>${state.game==='go'?'棋下在交叉点上':state.game==='cube'?'先找中心，再找伙伴':'先连成五颗'}</small>`;$('#lessonPanel').classList.add('show')}
const LEVEL_NAMES={easy:'小鸡',medium:'狐狸',hard:'狮子'};
function syncLevel(){$$('[data-level]').forEach(b=>{const active=b.dataset.level===state.level;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active?'true':'false');const s=b.querySelector('small');if(s){const text=s.textContent.replace(/^✓ 当前 · /,'');s.textContent=active?`✓ 当前 · ${text}`:text}})}

// Gomoku engine
function gmPut(points,v){points.forEach(([x,y])=>state.board[y][x]=v)}
function drawGM(){const W=660,pad=42,cell=(W-pad*2)/10,grad=ctx.createLinearGradient(0,0,W,W);grad.addColorStop(0,'#e7be7c');grad.addColorStop(1,'#c99552');ctx.fillStyle=grad;ctx.fillRect(0,0,W,W);ctx.strokeStyle='rgba(87,54,22,.68)';ctx.lineWidth=2;for(let i=0;i<11;i++){ctx.beginPath();ctx.moveTo(pad,pad+i*cell);ctx.lineTo(W-pad,pad+i*cell);ctx.stroke();ctx.beginPath();ctx.moveTo(pad+i*cell,pad);ctx.lineTo(pad+i*cell,W-pad);ctx.stroke()}[[3,3],[7,3],[5,5],[3,7],[7,7]].forEach(([x,y])=>{ctx.beginPath();ctx.arc(pad+x*cell,pad+y*cell,5,0,Math.PI*2);ctx.fillStyle='#714c27';ctx.fill()});for(let y=0;y<11;y++)for(let x=0;x<11;x++)if(state.board[y][x])drawStone(pad+x*cell,pad+y*cell,cell*.39,state.board[y][x]);if(state.hint){ctx.beginPath();ctx.arc(pad+state.hint.x*cell,pad+state.hint.y*cell,cell*.34,0,Math.PI*2);ctx.strokeStyle='#ff5148';ctx.lineWidth=6;ctx.setLineDash([10,8]);ctx.stroke();ctx.setLineDash([])}}
function drawStone(x,y,r,v){ctx.save();ctx.shadowColor='rgba(52,35,17,.35)';ctx.shadowBlur=9;ctx.shadowOffsetY=5;const g=ctx.createRadialGradient(x-r*.35,y-r*.45,r*.08,x,y,r);if(v===1){g.addColorStop(0,'#718088');g.addColorStop(.45,'#26353b');g.addColorStop(1,'#10181c')}else{g.addColorStop(0,'#fff');g.addColorStop(.55,'#f5f2ea');g.addColorStop(1,'#c9c6bd')}ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.restore()}
function gmCoords(e){const r=canvas.getBoundingClientRect(),s=canvas.width/r.width,p=42,c=(660-p*2)/10;return{x:Math.round(((e.clientX-r.left)*s-p)/c),y:Math.round(((e.clientY-r.top)*s-p)/c)}}
function gmClick(e){if(state.over||state.turn!==1||state.mode==='lesson')return;const{x,y}=gmCoords(e);if(x<0||y<0||x>10||y>10||state.board[y][x])return;if(state.mode==='puzzle')return gmPuzzleMove(x,y);state.board[y][x]=1;state.moves++;draw();if(gmWin(x,y,1))return finishBattle(true);state.turn=2;updateTurn();setTimeout(gmAI,380)}
function gmPuzzleMove(x,y){const[a,b]=state.puzzle.steps[state.puzzleStep];if(x!==a||y!==b){state.mistakes++;state.board[y][x]=1;draw();setTimeout(()=>{state.board[y][x]=0;if(state.mistakes>=2){state.hint={x:a,y:b};$('#coachText').textContent='这题很有挑战！红圈给你一个方向。'}else $('#coachText').textContent='这一步还不够有力，先想想对手会怎样回答。';draw();speak($('#coachText').textContent)},350);return}state.hint=null;state.board[y][x]=1;draw();if(state.puzzleStep===state.puzzle.steps.length-1)return finishPuzzle();state.turn=2;updateTurn();setTimeout(()=>{const r=state.puzzle.replies[state.puzzleStep];if(r)state.board[r[1]][r[0]]=2;state.puzzleStep++;state.turn=1;$('#coachText').textContent='对手挡了一边。现在找出下一步最强的进攻！';gmPuzzleProgress();updateTurn();draw();speak($('#coachText').textContent)},430)}
function gmPuzzleProgress(){$('#moveCount').textContent=`第 ${state.puzzleIndex+1} / 6 题`;$('#puzzleProgress').textContent=state.puzzle.steps.length>1?`连续题：第 ${state.puzzleStep+1} / ${state.puzzle.steps.length} 步`:'找到这一题的关键手'}
function gmCountOn(b,x,y,dx,dy,v){let n=0;for(let i=1;i<5;i++){const a=x+dx*i,c=y+dy*i;if(a<0||c<0||a>10||c>10||b[c][a]!==v)break;n++}return n}
function gmWinOn(b,x,y,v){return[[1,0],[0,1],[1,1],[1,-1]].some(([a,c])=>1+gmCountOn(b,x,y,a,c,v)+gmCountOn(b,x,y,-a,-c,v)>=5)}
function gmWin(x,y,v){return gmWinOn(state.board,x,y,v)}
function gmCount(x,y,dx,dy,v){return gmCountOn(state.board,x,y,dx,dy,v)}
function gmAvail(b=state.board){const a=[];for(let y=0;y<11;y++)for(let x=0;x<11;x++)if(!b[y][x])a.push({x,y});return a}
function gmWould(x,y,v){state.board[y][x]=v;const w=gmWin(x,y,v);state.board[y][x]=0;return w}
function gmCandidates(b){let stones=0;const set=new Set();for(let y=0;y<11;y++)for(let x=0;x<11;x++)if(b[y][x]){stones++;for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const a=x+dx,c=y+dy;if(a>=0&&a<11&&c>=0&&c<11&&!b[c][a])set.add(a+','+c)}}if(!stones)return[{x:5,y:5}];return[...set].map(k=>{const[x,y]=k.split(',').map(Number);return{x,y}})}
function gmPattern(b,x,y,v){if(b[y][x])return{score:-Infinity,openFour:0,openThree:0};b[y][x]=v;let score=0,openFour=0,openThree=0;for(const[dx,dy]of[[1,0],[0,1],[1,1],[1,-1]]){const left=gmCountOn(b,x,y,-dx,-dy,v),right=gmCountOn(b,x,y,dx,dy,v),n=1+left+right;const lx=x-dx*(left+1),ly=y-dy*(left+1),rx=x+dx*(right+1),ry=y+dy*(right+1);const open=(lx>=0&&lx<11&&ly>=0&&ly<11&&!b[ly][lx]?1:0)+(rx>=0&&rx<11&&ry>=0&&ry<11&&!b[ry][rx]?1:0);if(n>=5)score+=10000000;else if(n===4&&open===2){score+=900000;openFour++}else if(n===4&&open===1)score+=180000;else if(n===3&&open===2){score+=52000;openThree++}else if(n===3&&open===1)score+=8000;else if(n===2&&open===2)score+=1400;else score+=n*n*(open+1)*12}b[y][x]=0;if(openFour>=1&&openThree>=1)score+=700000;if(openThree>=2)score+=420000;return{score,openFour,openThree}}
