function gmRank(b,v){const enemy=v===1?2:1;return gmCandidates(b).map(c=>{const own=gmPattern(b,c.x,c.y,v),opp=gmPattern(b,c.x,c.y,enemy);return{...c,s:own.score*1.12+opp.score,threat:own.openFour+own.openThree>=2?'双重威胁':own.openFour?'活四':own.openThree?'活三':'布局'}}).sort((a,c)=>c.s-a.s)}
