const XQ_TEXT={r:{r:'車',n:'馬',b:'相',a:'仕',k:'帥',c:'炮',p:'兵'},b:{r:'車',n:'馬',b:'象',a:'士',k:'將',c:'砲',p:'卒'}};
function xqEmpty(){return Array.from({length:10},()=>Array(9).fill(null))}
