function xqEvaluate(b){if(!xqHasKing(b,'r'))return 1000000;if(!xqHasKing(b,'b'))return-1000000;let score=0;for(let y=0;y<10;y++)for(let x=0;x<9;x++){const p=b[y][x];if(!p)continue;const v=XQ_VALUE[p.t]+xqPieceBonus(p,y,x);score+=(p.c==='b'?1:-1)*v}score+=xqAttackBalance(b);if(xqCheck(b,'r'))score+=150;if(xqCheck(b,'b'))score-=190;return score}
function xqMovePriority(b,m,c){const n=xqAfter(b,m),enemy=c==='b'?'r':'b',side=c==='b'?1:-1;if(!xqHasKing(n,enemy))return 10000000;let score=m.capture?XQ_VALUE[m.capture.t]*18-XQ_VALUE[b[m.fy][m.fx].t]*.12:0;if(xqCheck(n,enemy))score+=420;score+=(5-Math.abs(m.tx-4))*5;score+=side*(xqEvaluate(n)-xqEvaluate(b))*.45;return score}
