let xqSearchNodes=0;
const xqTT=new Map();
function xqKey(b,c,depth,extension){return c+depth+extension+b.map(row=>row.map(p=>p?p.c+p.t:'--').join('')).join('')}
function xqSearch(b,c,depth,alpha,beta,ply,extension=1){xqSearchNodes++;if(!xqHasKing(b,'r'))return 1000000-ply;if(!xqHasKing(b,'b'))return-1000000+ply;if(depth<=0){if(extension&&xqCheck(b,c)){depth=1;extension=0}else return xqEvaluate(b)}const key=xqKey(b,c,depth,extension),cached=xqTT.get(key);if(cached!==undefined)return cached;const moves=xqMoves(b,c);if(!moves.length)return c==='r'?900000-ply:-900000+ply;const limit=depth>=3?10:depth===2?8:6,ranked=xqRankMoves(b,moves,c).slice(0,limit);let cut=false;if(c==='b'){let best=-Infinity;for(const {m} of ranked){best=Math.max(best,xqSearch(xqAfter(b,m),'r',depth-1,alpha,beta,ply+1,extension));alpha=Math.max(alpha,best);if(beta<=alpha){cut=true;break}}if(!cut)xqTT.set(key,best);return best}let best=Infinity;for(const {m} of ranked){best=Math.min(best,xqSearch(xqAfter(b,m),'b',depth-1,alpha,beta,ply+1,extension));beta=Math.min(beta,best);if(beta<=alpha){cut=true;break}}if(!cut)xqTT.set(key,best);return best}
function xqEasyMove(moves,b=state.board){const win=moves.find(m=>m.capture?.t==='k');if(win)return win;const ranked=xqRankMoves(b,moves,'b'),start=Math.min(ranked.length-1,Math.max(1,Math.floor(ranked.length*.35))),pool=ranked.slice(start);return pool[Math.floor(Math.random()*pool.length)].m}
function xqMediumMove(moves,b=state.board){xqTT.clear();let best=moves[0],bestScore=-Infinity;for(const m of moves){const next=xqAfter(b,m);if(!xqHasKing(next,'r'))return m;const score=xqSearch(next,'r',1,-Infinity,Infinity,1,0)+xqMovePriority(b,m,'b')*.04;if(score>bestScore){bestScore=score;best=m}}return best}
function xqHardMove(moves,b=state.board){xqSearchNodes=0;xqTT.clear();const ranked=xqRankMoves(b,moves,'b');if(ranked[0]?.m.capture?.t==='k')return ranked[0].m;const candidates=ranked.slice(0,Math.min(26,ranked.length));let best=candidates[0].m,bestScore=-Infinity;for(const {m} of candidates){const score=xqSearch(xqAfter(b,m),'r',3,-Infinity,Infinity,1,1);if(score>bestScore){bestScore=score;best=m}}return best}
function xqAI(){if(state.over)return;const moves=xqMoves(state.board,'b');if(!moves.length)return finishBattle(true);let pick;if(state.level==='easy')pick=xqEasyMove(moves);else if(state.level==='medium')pick=xqMediumMove(moves);else pick=xqHardMove(moves);const cap=xqApply(pick);state.moves++;draw();if(cap?.t==='k')return finishBattle(false);state.turn='r';updateTurn();if(xqCheck(state.board,'r')){$('#coachText').textContent=`${LEVEL_NAMES[state.level]}将军了！请用躲、挡、吃来保护自己的帅。`;speak('将军警报，请保护自己的帅')}else if(state.level==='hard')$('#coachText').textContent=`狮子刚才推演了 ${xqSearchNodes.toLocaleString()} 个局面。轮到你想出更好的计划！`;else if(state.level==='medium')$('#coachText').textContent='狐狸已经想过你下一步最可能的反击。轮到你啦！'}
